PKGS.getPkgForIdentifier = function (pkgIdentifier) { return PKGS[pkgIdentifier] || []; };
PKGS.setPkgForIdentifier = function (pkgIdentifier, pkg) { PKGS[pkgIdentifier] = pkg || []; };
PKGS.addToPkgForIdentifier = function (pkgIdentifier, pkgAdditions) { PKGS[pkgIdentifier] = (PKGS[pkgIdentifier] || []).concat(pkgAdditions || []); };
PKGS.getFactionGamePkgIdentifier = function (factionIdentifier) { return 'faction_game_' + factionIdentifier; };
PKGS.getFactionInspectPkgIdentifier = function (factionIdentifier) { return 'faction_inspect_' + factionIdentifier; };
