PKGS.getCardInspectPkgIdentifier = function (cardIdentifier) { return 'card_inspect_' + Cards.getNonPrismaticCardId(cardIdentifier); };
PKGS.getCardBackPkgIdentifier = function (cardBackIdentifier) { return 'card_back_' + parseInt(cardBackIdentifier); };
PKGS.getBattleMapPkgIdentifier = function (battleMapIdentifier) { return 'battle_map_' + battleMapIdentifier; };
PKGS.getChapterPkgIdentifier = function (chapterIdentifier) { return 'chapter_' + chapterIdentifier; };
PKGS.getChallengePkgIdentifier = function (challengeIdentifier) { return 'challenge_' + challengeIdentifier; };

module.exports = PKGS;

