          title = '<p>' + i18next.t('shop.eyos_orb_set_complete_message', { card_set_name: cardSetData.name }) + '</p>';
          this.bloodbornTooltipElement = $('div.' + cardSetData.devName, this.ui.tabBody).find('li:first');
