    chromaticProgram.initWithVertexShaderByteArray("#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\nattribute vec4 a_position;\nattribute vec2 a_texCoord;\n\nuniform float u_time;\nuniform vec2 u_resolution;\nuniform vec2 u_aberrationScale;\n\nvarying vec2 v_texCoord;\nvarying vec3 v_aberration;\nvarying vec2 v_rCoord;\nvarying vec2 v_gCoord;\nvarying vec2 v_bCoord;\n\nvoid main() {\n  v_texCoord = a_texCoord;\n  float aberrationTime = u_time;\n\tv_aberration = vec3(\n\t\tsin(aberrationTime) * (1.0 + sin(aberrationTime * 3.0) * 0.5) * 0.05 * u_aberrationScale.x,\n\t\tcos(aberrationTime * 1.5) * (1.0 + cos(aberrationTime * 2.0) * 0.5) * 0.05 * u_aberrationScale.y,\n\t\t0.0\n\t);\n\tv_rCoord = vec2(v_texCoord.x + v_aberration.x, v_texCoord.y + v_aberration.y);\n\tv_gCoord = vec2(v_texCoord.x + v_aberration.z, v_texCoord.y - v_aberration.z);\n\tv_bCoord = vec2(v_texCoord.x - v_aberration.x, v_texCoord.y - v_aberration.y);\n\tgl_Position = (CC_PMatrix * CC_MVMatrix) * a_position;\n}\n", "#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\n// uncomment if using noise map based chromatic shader\n//uniform sampler2D u_noiseMap;\nuniform float u_time;\nuniform vec2 u_resolution;\nuniform float u_frequency;\nuniform float u_amplitude;\nuniform float u_smoothstepMin;\nuniform float u_smoothstepMax;\n\nvarying vec2 v_texCoord;\nvarying vec3 v_aberration;\nvarying vec2 v_rCoord;\nvarying vec2 v_gCoord;\nvarying vec2 v_bCoord;\n\n//\n// Description : Array and textureless GLSL 2D simplex noise function.\n//      Author : Ian McEwan, Ashima Arts.\n//  Maintainer : ijm\n//     Lastmod : 20110822 (ijm)\n//     License : Copyright (C) 2011 Ashima Arts. All rights reserved.\n//               Distributed under the MIT License. See LICENSE file.\n//               https://github.com/ashima/webgl-noise\n//\n\nvec3 mod289_1_0(in vec3 x) {\n  return x - floor(x * (1.0 / 289.0)) * 289.0;\n}\n\nvec2 mod289_1_0(in vec2 x) {\n  return x - floor(x * (1.0 / 289.0)) * 289.0;\n}\n\nvec3 permute_1_1(in vec3 x) {\n  return mod289_1_0(((x*34.0)+1.0)*x);\n}\n\nfloat getNoise2D_1_2(in vec2 v) {\n  const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);\n\n\t// First corner\n  vec2 i  = floor(v + dot(v, C.yy) );\n  vec2 x0 = v -   i + dot(i, C.xx);\n\n\t// Other corners\n  vec2 i1;\n  //i1.x = step( x0.y, x0.x ); // x0.x > x0.y ? 1.0 : 0.0\n  //i1.y = 1.0 - i1.x;\n  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);\n  // x0 = x0 - 0.0 + 0.0 * C.xx ;\n  // x1 = x0 - i1 + 1.0 * C.xx ;\n  // x2 = x0 - 1.0 + 2.0 * C.xx ;\n  vec4 x12 = x0.xyxy + C.xxzz;\n  x12.xy -= i1;\n\n\t// Permutations\n  i = mod289_1_0(i); // Avoid truncation effects in permutation\n  vec3 p = permute_1_1( permute_1_1( i.y + vec3(0.0, i1.y, 1.0 )) + i.x + vec3(0.0, i1.x, 1.0 ));\n\n  vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);\n  m = m*m ;\n  m = m*m ;\n\n\t// Gradients: 41 points uniformly over a line, mapped onto a diamond.\n\t// The ring size 17*17 = 289 is close to a multiple of 41 (41*7 = 287)\n\n  vec3 x = 2.0 * fract(p * C.www) - 1.0;\n  vec3 h = abs(x) - 0.5;\n  vec3 ox = floor(x + 0.5);\n  vec3 a0 = x - ox;\n\n\t// Normalise gradients implicitly by scaling m\n\t// Approximation of: m *= inversesqrt( a0*a0 + h*h );\n  m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );\n\n\t// Compute final noise value at P\n  vec3 g;\n  g.x  = a0.x  * x0.x  + h.x  * x0.y;\n  g.yz = a0.yz * x12.xz + h.yz * x12.yw;\n  return 130.0 * dot(m, g);\n}\n\n\n\n\nfloat fbm_2_3(in vec2 coord, in float frequency, in float amplitude)\n{\n\tfloat fractalSum = 0.0;\n\tfor (int i = 0; i < 2; i++) {\n\t\tfractalSum += abs((getNoise2D_1_2(coord * frequency) - 0.5) * 2.0) * amplitude;\n\t\tfrequency *= 2.0;\n\t\tamplitude *= 0.5;\n\t\tcoord *= 2.0;\n\t}\n\treturn fractalSum;\n}\n\nfloat getNoiseRotatedFBM_2_4 (in vec2 coord_2_5, in float time_2_6, in float frequency_2_7, in float amplitude_2_8) {\n\tvec2 basis = vec2(fbm_2_3(coord_2_5 - time_2_6 * 1.6, frequency_2_7, amplitude_2_8), fbm_2_3(coord_2_5 + time_2_6 * 1.7, frequency_2_7, amplitude_2_8));\n\tbasis = (basis - 0.5) * 0.2;\n\tcoord_2_5 += basis;\n\tfloat c = cos(time_2_6 * 0.2);\n\tfloat s = sin(time_2_6 * 0.2);\n\tmat2 timeMat = mat2(c, -s, s, c);\n\treturn fbm_2_3(coord_2_5 * timeMat, frequency_2_7, amplitude_2_8);\n}\n\n\n\n// uncomment if using noise map based chromatic shader\n//#pragma glslify: getNoiseRotatedFBMFromTexture = require(./helpers/NoiseRotatedFBMFromTexture.glsl)\n\nvoid main() {\n\tvec2 screenTexCoord = gl_FragCoord.xy / u_resolution - 0.5;\n\tscreenTexCoord.x *= u_resolution.x / u_resolution.y;\n  vec4 color = texture2D(CC_Texture0, v_texCoord);\n\n  // fbm noise\n  float noise = getNoiseRotatedFBM_2_4(screenTexCoord, u_time, u_frequency, u_amplitude);\n\t// uncomment if using noise map based chromatic shader\n  //float noise = getNoiseRotatedFBMFromTexture(screenTexCoord, u_time, u_frequency, u_amplitude, u_noiseMap);\n  float invNoise = 1.0 - smoothstep(u_smoothstepMin, u_smoothstepMax, noise);\n\n  // fake aberration\n  vec3 chromatic;\n  float modifier = (1.0 - v_aberration.x * 0.5);\n  chromatic.r = texture2D(CC_Texture0, v_rCoord).r * modifier;\n  chromatic.g = texture2D(CC_Texture0, v_gCoord).g * modifier;\n  chromatic.b = texture2D(CC_Texture0, v_bCoord).b * modifier;\n\n\tgl_FragColor = vec4(chromatic, color.a * invNoise);\n}\n");
