    dissolveProgram.initWithVertexShaderByteArray("#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\nattribute vec4 a_position;\nattribute vec2 a_texCoord;\nattribute vec4 a_color;\n\nvarying vec4 v_fragmentColor;\nvarying vec2 v_texCoord;\n\nvoid main() {\n\tv_texCoord = a_texCoord;\n\tv_fragmentColor = a_color;\n\tgl_Position = (CC_PMatrix * CC_MVMatrix) * a_position;\n}\n", "#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\n// CC_Texture0 is texture to dissolve\n\nuniform float u_seed;\nuniform float u_frequency;\nuniform float u_amplitude;\nuniform float u_vignetteStrength;\nuniform float u_edgeFalloff;\nuniform float u_time;\n\nvarying vec2 v_texCoord;\nvarying vec4 v_fragmentColor;\n\nfloat getHash_1_0 (in vec2 coord_1_1) {\n\treturn fract(sin(dot(coord_1_1, vec2(234.1235, 123.752))) * 34702.0);\n}\n\nfloat getNoise_1_2 (in vec2 coord_1_1) {\n\tvec2 coordWhole = floor(coord_1_1);\n\tvec2 coordFraction = fract(coord_1_1);\n\tvec2 smoothFraction = coordFraction * coordFraction * (3.0 - 2.0 * coordFraction);\n\n\tfloat bl = getHash_1_0(coordWhole);\n\tfloat br = getHash_1_0(vec2(coordWhole.x + 1.0, coordWhole.y));\n\tfloat tl = getHash_1_0(vec2(coordWhole.x, coordWhole.y + 1.0));\n\tfloat tr = getHash_1_0(vec2(coordWhole.x + 1.0, coordWhole.y + 1.0));\n\tfloat b = mix(bl, br, smoothFraction.x);\n\tfloat t = mix(tl, tr, smoothFraction.x);\n\n\treturn mix(b, t, smoothFraction.y);\n}\n\nfloat getNoiseFBM_1_3 (in vec2 coord_1_1, in float time_1_4, in float frequency_1_5, in float amplitude_1_6) {\n\tfloat fractalSum = 0.0;\n\n\ttime_1_4 = time_1_4 * 3.141592653589793 * 2.0 + 3.141592653589793;\n\n\t// fractional brownian motion\n\tfor (int i = 0; i < 2; i++) {\n\t\tvec2 offset = vec2(cos(time_1_4 + frequency_1_5), sin(time_1_4 + frequency_1_5)) * (frequency_1_5 * 0.1);\n\t\tfloat noise = getNoise_1_2(coord_1_1 * frequency_1_5 + offset);\n\t\tfractalSum += noise * amplitude_1_6;\n\t\tamplitude_1_6 *= .5;\n\t\tfrequency_1_5 *= 2.0;\n\t}\n\n\treturn fractalSum;\n}\n\n\n\n\nvoid main () {\n\tvec4 color = texture2D(CC_Texture0, v_texCoord);\n\n\t// vignette\n\tvec2 noiseCenterDiff = v_texCoord - vec2(0.5);\n  float noiseCenterOffset = u_time + 0.25;\n  noiseCenterOffset = (noiseCenterOffset * noiseCenterOffset * noiseCenterOffset * noiseCenterOffset) + 0.25;\n\tfloat noiseCenterDist = length(noiseCenterDiff) * 5.0 * noiseCenterOffset + noiseCenterOffset;\n  noiseCenterDist = noiseCenterDist * noiseCenterDist * noiseCenterDist * noiseCenterDist * noiseCenterDist * noiseCenterDist;\n\tfloat noiseVignette = max(0.0, 1.0 - noiseCenterDist) * u_vignetteStrength;\n\n\t// noise\n\tfloat noise = getNoiseFBM_1_3(vec2(u_seed) + v_texCoord, 0.0, u_frequency, max(0.0, u_amplitude + u_time - noiseVignette));\n\tfloat noiseRangeMin = 0.99 - u_time;\n\tfloat noiseRangeMax = 1.0 - u_time;\n\tfloat noiseSmooth = 1.0 - smoothstep(noiseRangeMin, noiseRangeMax, noise);\n\tfloat noiseEdge = fract(1.0 - smoothstep(noiseRangeMin, noiseRangeMax + u_edgeFalloff, noise));\n\n\tgl_FragColor = v_fragmentColor * vec4(max(color.rgb, ceil(noiseEdge)), color.a * (noiseSmooth + noiseEdge));\n}\n");
