    const fireRingProgram = new cc.GLProgram();
    fireRingProgram.initWithVertexShaderByteArray("#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\nattribute vec4 a_position;\nattribute vec2 a_texCoord;\nattribute vec4 a_color;\n\nvarying vec4 v_fragmentColor;\nvarying vec2 v_texCoord;\n\nvoid main() {\n\tv_texCoord = a_texCoord;\n\tv_fragmentColor = a_color;\n\tgl_Position = (CC_PMatrix * CC_MVMatrix) * a_position;\n}\n", "#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\n#define COMPLEXITY \t2.0\n\n// CC_Texture0 is noise texture\nuniform float u_phase;\nuniform float u_time;\nuniform vec3 u_color;\nuniform vec2 u_texResolution;\n\nvarying vec2 v_texCoord;\nvarying vec4 v_fragmentColor;\n\n//\n// Description : Array and textureless GLSL 2D/3D/4D simplex\n//               noise functions.\n//      Author : Ian McEwan, Ashima Arts.\n//  Maintainer : ijm\n//     Lastmod : 20110822 (ijm)\n//     License : Copyright (C) 2011 Ashima Arts. All rights reserved.\n//               Distributed under the MIT License. See LICENSE file.\n//               https://github.com/ashima/webgl-noise\n//\n\nvec3 mod289_1_0(in vec3 x) {\n  return x - floor(x * (1.0 / 289.0)) * 289.0;\n}\n\nvec4 mod289_1_0(in vec4 x) {\n  return x - floor(x * (1.0 / 289.0)) * 289.0;\n}\n\nvec4 permute_1_1(in vec4 x) {\n     return mod289_1_0(((x*34.0)+1.0)*x);\n}\n\nvec4 taylorInvSqrt_1_2(in vec4 r) {\n  return 1.79284291400159 - 0.85373472095314 * r;\n}\n\nfloat getNoise3D_1_3(in vec3 v) {\n  const vec2  C = vec2(1.0/6.0, 1.0/3.0);\n  const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);\n\n\t// First corner\n  vec3 i = floor(v + dot(v, C.yyy) );\n  vec3 x0 = v - i + dot(i, C.xxx);\n\n\t// Other corners\n  vec3 g = step(x0.yzx, x0.xyz);\n  vec3 l = 1.0 - g;\n  vec3 i1 = min( g.xyz, l.zxy );\n  vec3 i2 = max( g.xyz, l.zxy );\n  vec3 x1 = x0 - i1 + C.xxx;\n  vec3 x2 = x0 - i2 + C.yyy;\n  vec3 x3 = x0 - D.yyy;\n\n\t// Permutations\n  i = mod289_1_0(i);\n  vec4 p = permute_1_1( permute_1_1( permute_1_1(i.z + vec4(0.0, i1.z, i2.z, 1.0 )) + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));\n\n\t// Gradients: 7x7 points over a square, mapped onto an octahedron.\n\t// The ring size 17*17 = 289 is close to a multiple of 49 (49*6 = 294)\n  float n_ = 0.142857142857;\n  vec3  ns = n_ * D.wyz - D.xzx;\n\n  vec4 j = p - 49.0 * floor(p * ns.z * ns.z);\n\n  vec4 x_ = floor(j * ns.z);\n  vec4 y_ = floor(j - 7.0 * x_ );\n\n  vec4 x = x_ *ns.x + ns.yyyy;\n  vec4 y = y_ *ns.x + ns.yyyy;\n  vec4 h = 1.0 - abs(x) - abs(y);\n\n  vec4 b0 = vec4( x.xy, y.xy );\n  vec4 b1 = vec4( x.zw, y.zw );\n\n  //vec4 s0 = vec4(lessThan(b0,0.0))*2.0 - 1.0;\n  //vec4 s1 = vec4(lessThan(b1,0.0))*2.0 - 1.0;\n  vec4 s0 = floor(b0)*2.0 + 1.0;\n  vec4 s1 = floor(b1)*2.0 + 1.0;\n  vec4 sh = -step(h, vec4(0.0));\n\n  vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;\n  vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;\n\n  vec3 p0 = vec3(a0.xy,h.x);\n  vec3 p1 = vec3(a0.zw,h.y);\n  vec3 p2 = vec3(a1.xy,h.z);\n  vec3 p3 = vec3(a1.zw,h.w);\n\n\t//Normalise gradients\n  vec4 norm = taylorInvSqrt_1_2(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));\n  p0 *= norm.x;\n  p1 *= norm.y;\n  p2 *= norm.z;\n  p3 *= norm.w;\n\n\t// Mix final noise value\n  vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);\n  m = m * m;\n  return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3) ) );\n}\n\n\n\n\n// TODO: replace with helper abs fbm octaves module when glslify fixes: https://github.com/stackgl/glslify/issues/44\nfloat getNoiseAbsFBMOctaves3(in vec3 v) {\n\tfloat res = 0.0;\n\tfloat scale = 1.0;\n\tfor(int i=0; i<3; i++) {\n\t\tres += abs(getNoise3D_1_3(v)) * scale;\n\t\tv *= vec3(2.0);\n\t\tscale *= 0.5;\n\t}\n\treturn res;\n}\n\nvec3 calc_pal(in float x) {\n\tvec3 col = mix(vec3(1.0, 1.0, 1.0), u_color, smoothstep(1.4, 1.6, x));\n\tcol = mix(col,\tu_color/5.0, smoothstep(1.5, 1.8, x));\n\tcol = mix(col, vec3(0.0, 0.0, 0.0), smoothstep(1.8, 2.0, x));\n\treturn col;\n}\n\nvoid main() {\n\tfloat t = u_time * 0.25;\n\tfloat phase = u_phase + 0.5;\n\n\tvec2 aspect = vec2(u_texResolution.x / u_texResolution.y, 1.0);\n\tvec2 uv = v_texCoord.xy;\n\tvec2 p = (uv * 4.0 - 2.0) * aspect;\n\n\t// makes a ring\n\t// vec2 polar = vec2(atan(p.x-t, p.y), length(p) * 0.9);\n\n\tvec2 polar = vec2(atan(p.x, p.y), (length(p) + 0.1) * phase);\n\tfloat dist = polar.y;\n\n\t// without rotation:\n\t// vec2 dom = vec2(polar.x, polar.y - t) * COMPLEXITY;\n\n\t// with rotation\n\t// vec2 dom = vec2(polar.x - t, polar.y - t) * COMPLEXITY;\n\n\tvec2 dom = vec2(polar.x, polar.y - t) * COMPLEXITY;\n\tfloat turb = dist*phase + 0.67/phase + getNoiseAbsFBMOctaves3(vec3(dom, t)) * (0.35/phase);\n\tvec3 color = calc_pal(turb * 0.95);\n\tcolor = mix(vec3(0.0), color, smoothstep(0.5/phase, 0.7/phase, dist*turb));\n\n\tgl_FragColor = v_fragmentColor * vec4(color, 1.0);\n}\n");
