    glowImageMapRippleProgram.initWithVertexShaderByteArray("#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\nattribute vec4 a_position;\nattribute vec2 a_texCoord;\nattribute vec4 a_color;\n\nvarying vec4 v_fragmentColor;\nvarying vec2 v_texCoord;\n\nvoid main() {\n\tv_texCoord = a_texCoord;\n\tv_fragmentColor = a_color;\n\tgl_Position = (CC_PMatrix * CC_MVMatrix) * a_position;\n}\n", "#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\nuniform float u_time;\nuniform vec2 u_texResolution;\nuniform float u_intensity;\n\nvarying vec2 v_texCoord;\nvarying vec4 v_fragmentColor;\n\n//\n// Description : Array and textureless GLSL 2D simplex noise function.\n//      Author : Ian McEwan, Ashima Arts.\n//  Maintainer : ijm\n//     Lastmod : 20110822 (ijm)\n//     License : Copyright (C) 2011 Ashima Arts. All rights reserved.\n//               Distributed under the MIT License. See LICENSE file.\n//               https://github.com/ashima/webgl-noise\n//\n\nvec3 mod289_1_0(in vec3 x) {\n  return x - floor(x * (1.0 / 289.0)) * 289.0;\n}\n\nvec2 mod289_1_0(in vec2 x) {\n  return x - floor(x * (1.0 / 289.0)) * 289.0;\n}\n\nvec3 permute_1_1(in vec3 x) {\n  return mod289_1_0(((x*34.0)+1.0)*x);\n}\n\nfloat getNoise2D_1_2(in vec2 v) {\n  const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);\n\n\t// First corner\n  vec2 i  = floor(v + dot(v, C.yy) );\n  vec2 x0 = v -   i + dot(i, C.xx);\n\n\t// Other corners\n  vec2 i1;\n  //i1.x = step( x0.y, x0.x ); // x0.x > x0.y ? 1.0 : 0.0\n  //i1.y = 1.0 - i1.x;\n  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);\n  // x0 = x0 - 0.0 + 0.0 * C.xx ;\n  // x1 = x0 - i1 + 1.0 * C.xx ;\n  // x2 = x0 - 1.0 + 2.0 * C.xx ;\n  vec4 x12 = x0.xyxy + C.xxzz;\n  x12.xy -= i1;\n\n\t// Permutations\n  i = mod289_1_0(i); // Avoid truncation effects in permutation\n  vec3 p = permute_1_1( permute_1_1( i.y + vec3(0.0, i1.y, 1.0 )) + i.x + vec3(0.0, i1.x, 1.0 ));\n\n  vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);\n  m = m*m ;\n  m = m*m ;\n\n\t// Gradients: 41 points uniformly over a line, mapped onto a diamond.\n\t// The ring size 17*17 = 289 is close to a multiple of 41 (41*7 = 287)\n\n  vec3 x = 2.0 * fract(p * C.www) - 1.0;\n  vec3 h = abs(x) - 0.5;\n  vec3 ox = floor(x + 0.5);\n  vec3 a0 = x - ox;\n\n\t// Normalise gradients implicitly by scaling m\n\t// Approximation of: m *= inversesqrt( a0*a0 + h*h );\n  m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );\n\n\t// Compute final noise value at P\n  vec3 g;\n  g.x  = a0.x  * x0.x  + h.x  * x0.y;\n  g.yz = a0.yz * x12.xz + h.yz * x12.yw;\n  return 130.0 * dot(m, g);\n}\n\n\n\n\n// TODO: replace with helper abs fbm octaves module when glslify fixes: https://github.com/stackgl/glslify/issues/44\nfloat getNoiseAbsFBMOctaves4(in vec2 v) {\n\tfloat res = 0.0;\n\tfloat scale = 1.0;\n\tfor(int i=0; i<4; i++) {\n\t\tres += abs(getNoise2D_1_2(v)) * scale;\n\t\tv *= vec2(2.0);\n\t\tscale *= 0.5;\n\t}\n\treturn res;\n}\n\nvoid main() {\n\tfloat t = u_time;\n\tfloat aspect = u_texResolution.x / u_texResolution.y;\n\n\tvec2 uv = v_texCoord;\n\n\tvec2 dom = vec2((uv.x - t) * aspect, uv.y + t) * 0.5;\n\tfloat turb = getNoiseAbsFBMOctaves4(dom);\n\n\tvec2 uv2 = uv + vec2(turb*.04);\n\tvec4 mapColor = texture2D(CC_Texture0,uv2);\n\n\tgl_FragColor = mapColor;\n}\n");
