    const coreGemEdgesAndColorizeFragmentProgram = new cc.GLProgram();
    coreGemEdgesAndColorizeFragmentProgram.initWithVertexShaderByteArray("#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\nattribute vec4 a_position;\nattribute vec2 a_texCoord;\nattribute vec4 a_color;\n\nvarying vec4 v_fragmentColor;\nvarying vec2 v_texCoord;\n\nvoid main() {\n\tv_texCoord = a_texCoord;\n\tv_fragmentColor = a_color;\n\tgl_Position = (CC_PMatrix * CC_MVMatrix) * a_position;\n}\n", "#define GLSLIFY 1\n// glslify blows up unless first line is comment or empty\nvarying vec2 v_texCoord;\nuniform vec2 u_texResolution;\nuniform vec3 u_colorBlackPoint;\nuniform vec3 u_colorMidPoint;\n\n\nfloat threshold(in float thr1, in float thr2 , in float val) {\n\tif (val < thr1) {return 0.0;}\n\tif (val > thr2) {return 1.0;}\n\treturn val;\n}\n\n// averaged pixel difference from 3 color channels\nfloat diff(in vec4 pix1, in vec4 pix2) {\n  return (\n    abs(pix1.r - pix2.r) +\n    abs(pix1.g - pix2.g) +\n    abs(pix1.b - pix2.b)\n  ) / 3.0;\n}\n\n// returns pixel color\nfloat IsEdge(in vec2 coords){\n\tfloat dx = 1.0 / u_texResolution.x /*image width*/;\n\tfloat dy = 1.0 / u_texResolution.y /*image height*/;\n\tvec4 pix[9];\n\n\tpix[0] = texture2D(CC_Texture0, coords + vec2( -1.0 * dx,  -1.0 * dy));\n\tpix[1] = texture2D(CC_Texture0, coords + vec2( -1.0 * dx ,  0.0 * dy));\n\tpix[2] = texture2D(CC_Texture0, coords + vec2( -1.0 * dx ,  1.0 * dy));\n\tpix[3] = texture2D(CC_Texture0, coords + vec2(  0.0 * dx , -1.0 * dy));\n\tpix[4] = texture2D(CC_Texture0, coords + vec2(  0.0 * dx ,  0.0 * dy));\n\tpix[5] = texture2D(CC_Texture0, coords + vec2(  0.0 * dx ,  1.0 * dy));\n\tpix[6] = texture2D(CC_Texture0, coords + vec2(  1.0 * dx , -1.0 * dy));\n\tpix[7] = texture2D(CC_Texture0, coords + vec2(  1.0 * dx ,  0.0 * dy));\n\tpix[8] = texture2D(CC_Texture0, coords + vec2(  1.0 * dx ,  1.0 * dy));\n\n\t// average color differences around neighboring pixels\n\tfloat delta = (\n\t\tdiff(pix[1],pix[7]) +\n\t\tdiff(pix[5],pix[3]) +\n\t\tdiff(pix[0],pix[8]) +\n\t\tdiff(pix[2],pix[6])\n\t)/4.0;\n\n\treturn delta; // threshold(0.25,0.4,clamp(3.0*delta,0.0,1.0));\n}\n\nvoid main() {\n\t// original color\n\tvec4 textureColor = texture2D(CC_Texture0, v_texCoord);\n\n\t// edge detection\n\tvec4 edgeColor = vec4(0.0,0.0,0.0,textureColor.a);\n    edgeColor.rgb = vec3(IsEdge(v_texCoord));\n\n\t// overlay edges over existing texture\n\tvec4 finalColor = textureColor + edgeColor;\n\n\t// temp\n\tvec3 blackPoint = u_colorBlackPoint; //\n\tvec3 midPoint = u_colorMidPoint; //\n\tvec3 whitePoint = vec3(1.0);\n\n\t// colorize\n\tfloat desaturated = (finalColor.r + finalColor.g + finalColor.b) / 3.0;\n\tvec3 colorized = mix(blackPoint, midPoint, smoothstep(0.0, 0.7, desaturated));\n\tcolorized = mix(colorized, whitePoint, smoothstep(0.7, 1.0, desaturated));\n\n\t// output final color\n\tgl_FragColor = vec4(colorized, finalColor.a);\n}\n");
